{
  "name": "IEEE 488.2 通用实验室仪器",
  "name_en": "Generic IEEE 488.2 Instrument",
  "manufacturer": "",
  "description": "符合 IEEE 488.2 标准的通用实验室测试仪器，可通过标准公共命令完成设备识别、复位、自检、触发、状态寄存器管理以及仪器状态的保存与恢复。此类设备常见于各类台式电子测量仪器中。",
  "description_en": "A generic laboratory test instrument compliant with the IEEE 488.2 standard. It supports standard common commands for identification, reset, self-test, triggering, status register handling, and instrument state save/recall. This device class is commonly found in bench electronic test instruments.",
  "tag_hints": [
    "IEEE 488.2",
    "GPIB instrument control",
    "SCPI common commands",
    "instrument status registers",
    "self-test and reset",
    "state save and recall"
  ],
  "actions": [
    {
      "action_name": "auto-clear_status_async",
      "description": "异步清除状态寄存器并清空错误队列",
      "description_en": "Asynchronously clear the status registers and error queue."
    },
    {
      "action_name": "auto-recall_state_async",
      "description": "异步从指定非易失存储位置恢复仪器状态",
      "description_en": "Asynchronously recall the instrument state from the specified non-volatile memory location."
    },
    {
      "action_name": "auto-reset_async",
      "description": "异步将仪器复位到出厂默认上电状态",
      "description_en": "Asynchronously reset the instrument to its factory default power-up state."
    },
    {
      "action_name": "auto-save_state_async",
      "description": "异步将当前仪器状态保存到指定非易失存储位置",
      "description_en": "Asynchronously save the current instrument state to the specified non-volatile memory location."
    },
    {
      "action_name": "auto-self_test_async",
      "description": "异步执行完整自检",
      "description_en": "Asynchronously perform a complete self-test."
    },
    {
      "action_name": "auto-set_operation_complete_bit_async",
      "description": "异步设置“操作完成”位，使当前操作结束后置位标准事件寄存器",
      "description_en": "Asynchronously set the Operation Complete bit so it is asserted in the Standard Event Register when the current operation finishes."
    },
    {
      "action_name": "auto-trigger_async",
      "description": "异步触发仪器执行一次触发操作",
      "description_en": "Asynchronously trigger the instrument to perform a trigger event."
    },
    {
      "action_name": "auto-wait_async",
      "description": "异步等待前序操作完成后再继续执行",
      "description_en": "Asynchronously wait for the preceding operation to complete before continuing."
    },
    {
      "action_name": "auto-wait_operation_complete_bit_async",
      "description": "异步等待全部挂起命令完成并返回操作完成指示",
      "description_en": "Asynchronously wait until all pending commands complete and return an operation-complete indication."
    },
    {
      "action_name": "auto-idn",
      "description": "读取仪器标识信息",
      "description_en": "Read the instrument identification information."
    },
    {
      "action_name": "auto-fitted_options",
      "description": "读取已安装选件信息",
      "description_en": "Read the installed option information."
    },
    {
      "action_name": "auto-reset",
      "description": "将仪器复位到出厂默认上电状态",
      "description_en": "Reset the instrument to its factory default power-up state."
    },
    {
      "action_name": "auto-self_test",
      "description": "执行完整自检",
      "description_en": "Perform a complete self-test."
    },
    {
      "action_name": "auto-wait",
      "description": "等待前序操作完成后再继续执行",
      "description_en": "Wait for the preceding operation to complete before continuing."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发仪器执行一次触发操作",
      "description_en": "Trigger the instrument to perform a trigger event."
    },
    {
      "action_name": "auto-status_byte",
      "description": "读取状态字节",
      "description_en": "Read the status byte."
    },
    {
      "action_name": "auto-service_request_enabled",
      "description": "获取或设置服务请求使能寄存器",
      "description_en": "Get or set the service request enable register."
    },
    {
      "action_name": "auto-event_status_reg",
      "description": "读取标准事件状态寄存器",
      "description_en": "Read the Standard Event Status Register."
    },
    {
      "action_name": "auto-event_status_enabled",
      "description": "获取或设置标准事件状态使能寄存器",
      "description_en": "Get or set the Standard Event Status Enable Register."
    },
    {
      "action_name": "auto-clear_status",
      "description": "清除状态寄存器并清空错误队列",
      "description_en": "Clear the status registers and error queue."
    },
    {
      "action_name": "auto-wait_operation_complete_bit",
      "description": "等待全部挂起命令完成并返回操作完成指示",
      "description_en": "Wait until all pending commands complete and return an operation-complete indication."
    },
    {
      "action_name": "auto-set_operation_complete_bit",
      "description": "设置“操作完成”位，使当前操作结束后置位标准事件寄存器",
      "description_en": "Set the Operation Complete bit so it is asserted in the Standard Event Register when the current operation finishes."
    },
    {
      "action_name": "auto-poweron_status_clear_enabled",
      "description": "获取或设置上电时是否清除状态相关寄存器",
      "description_en": "Get or set whether status-related registers are cleared at power-on."
    },
    {
      "action_name": "auto-recall_state",
      "description": "从指定非易失存储位置恢复仪器状态",
      "description_en": "Recall the instrument state from the specified non-volatile memory location."
    },
    {
      "action_name": "auto-save_state",
      "description": "将当前仪器状态保存到指定非易失存储位置",
      "description_en": "Save the current instrument state to the specified non-volatile memory location."
    }
  ]
}

